/**
 * Registers a handler for one event type. Call the return value to detach.
 *
 * The handler set is copy-on-write: a subscribe or unsubscribe that happens
 * while `emit()` is walking the set never mutates the collection being
 * iterated. Unsubscribe removes the handler from the live set, not from the
 * snapshot taken at subscribe time — a later subscriber copies that snapshot,
 * and deleting from the abandoned copy would leave the handler attached.
 */
export function subscribe<K extends TaskflowEventType>(
  type: K,
  handler: EventHandler<K>,
): Unsubscribe {
  const set: HandlerSet = new Set(handlers.get(type));
  set.add(handler as EventHandler<TaskflowEventType>);
  handlers.set(type, set);
  return () => {
    const current = handlers.get(type);
    if (current === undefined || !current.has(handler as EventHandler<TaskflowEventType>)) {
      return;
    }
    const next: HandlerSet = new Set(current);
    next.delete(handler as EventHandler<TaskflowEventType>);
    if (next.size === 0) handlers.delete(type);
    else handlers.set(type, next);
  };
}

